<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api, beijingTime, durationText, queryParams, currentAccountName, type Page } from './api'
import { errorMessage, statusLabel, servers, type Server } from './monitoring'
import RecordDelete from './RecordDelete.vue'
import MetricChart from './MetricChart.vue'
import type { EChartsOption } from 'echarts'
const props = defineProps<{ events?: boolean }>(), route = useRoute(), router = useRouter()
const checked=ref<Record<string,unknown>[]>([]),deletion=ref<InstanceType<typeof RecordDelete>>()
const tab = ref('current'), nodes = ref<Server[]>([]), items = ref<Record<string,unknown>[]>([]), total = ref(0), error = ref(''), detail = ref<Record<string,unknown>>()
const filter = reactive({ node:'', q:'', status:'', operation:'', source:'', recipient:'', page:1, page_size:20, hours:24, include_probes:false })
const isNotifications = computed(() => ['notifications','email'].includes(tab.value)), channel = computed(() => tab.value === 'email' ? 'email' : 'feishu')
const stats = ref<{ day:string; delivered:number; pending:number; retrying:number }[]>([])
const chart = computed<EChartsOption>(() => ({tooltip:{trigger:'axis'},legend:{bottom:0},grid:{left:45,right:20,top:20,bottom:55},xAxis:{type:'category',data:stats.value.map(v=>v.day)},yAxis:{type:'value'},series:[['delivered',channel.value==='email'?'已提交邮件服务器':'已送达'],['pending','待发送'],['retrying','重试中']].map(([key,label])=>({name:label!,type:'bar',stack:'messages',data:stats.value.map(v=>v[key as keyof typeof v] as number)}))}))
function parseRoute() {
 tab.value = props.events ? 'current' : ['current','history','notifications','email'].includes(String(route.query.tab)) ? String(route.query.tab) : 'current'
 for (const k of ['node','q','status','operation','source','recipient'] as const) filter[k] = typeof route.query[k] === 'string' ? String(route.query[k]) : ''
 filter.include_probes = route.query.include_probes === 'true'
 filter.page = Math.max(1,Number(route.query.page)||1); filter.hours = [24,168,720].includes(Number(route.query.hours)) ? Number(route.query.hours) : 24
}
function values() { return { ...filter, tab:props.events ? undefined : tab.value, status:isNotifications.value ? filter.status : undefined, source:!props.events && !isNotifications.value ? filter.source : undefined, operation:props.events ? filter.operation : undefined, include_probes:props.events ? filter.include_probes : undefined, recipient:channel.value==='email' && isNotifications.value ? filter.recipient : undefined } }
const documentHidden=ref(document.hidden)
const queried = ref(false), loading = ref(false), autoRefresh = ref(false), intervalSeconds = ref(30), lastUpdated = ref(0), countdown = ref(0)
const submitted = ref<Record<string,unknown>>(), changed = computed(() => props.events && !!submitted.value && ['node','q','operation','hours','include_probes'].some(k => values()[k as keyof ReturnType<typeof values>] !== submitted.value?.[k]))
let inputTimer:ReturnType<typeof setTimeout>|undefined, timer:ReturnType<typeof setInterval>|undefined, generation=0, disposed=false, busy=false, nextRefresh=0, queued=false
const preferenceKey = () => `webscan:event-refresh:${currentAccountName()}`
const refreshIntervals = [10,30,60,120,300]
function validInterval() { return refreshIntervals.includes(intervalSeconds.value) }
function schedule() { nextRefresh=autoRefresh.value&&validInterval()&&!changed.value&&!document.hidden ? Date.now()+intervalSeconds.value*1000 : 0; countdown.value=nextRefresh?intervalSeconds.value:0 }
function configureRefresh(){if(!validInterval())intervalSeconds.value=30;try{localStorage.setItem(preferenceKey(),String(intervalSeconds.value))}catch{}schedule()}
async function load() {
 if(disposed||document.hidden||(props.events&&!submitted.value))return
 if(busy){queued=true;return}busy=true;loading.value=true;const current=generation, email=channel.value, notifications=isNotifications.value
 const conditions=props.events ? {...submitted.value} : values()
 const query=queryParams({...conditions,start:Math.floor(Date.now()/1000)-Number(conditions.hours)*3600,history:tab.value==='history',channel:notifications?email:undefined})
 try {
 const endpoint=props.events?'/api/events':notifications?'/api/notifications':'/api/alerts';const data=await api<Page<Record<string,unknown>>>(`${endpoint}?${query}`)
 if(current===generation&&!disposed){items.value=data.items;total.value=data.total;checked.value=[];error.value='';queried.value=true;lastUpdated.value=Date.now()/1000
 if(!props.events&&Number(conditions.page)>Math.max(1,Math.ceil(data.total/20))){filter.page=Math.max(1,Math.ceil(data.total/20));void sync(filter.page)}
 if(props.events && Number(conditions.page)>Math.max(1,Math.ceil(data.total/20))){submitted.value={...conditions,page:Math.max(1,Math.ceil(data.total/20))};generation++;queued=true}}
 if(notifications){const result=await api<{items:typeof stats.value}>(`/api/notifications/stats?channel=${email}`);if(current===generation&&!disposed)stats.value=result.items}
 }catch(e){if(current===generation&&!disposed)error.value=errorMessage(e)}finally{busy=false;loading.value=false;if(!disposed&&queued){queued=false;void load()}else if(!disposed)schedule()}
}
function search(){clearTimeout(inputTimer);if(props.events){void sync();return}inputTimer=setTimeout(()=>void sync(),300)}
async function sync(page=1){clearTimeout(inputTimer);if(props.events){nextRefresh=0;const query=Object.fromEntries(queryParams(values()));await router.replace({path:route.path,query});return}filter.page=page;generation++;const query=Object.fromEntries(queryParams(values()));if(new URLSearchParams(Object.entries(query).sort()).toString()===new URLSearchParams(Object.entries(route.query as Record<string,string>).sort()).toString()){void load();return};await router.replace({path:route.path,query})}
async function submit(){if(!props.events){void sync();return}generation++;submitted.value={...values(),page:1};filter.page=1;await sync();void load()}
function paginate(page:number){if(!props.events){filter.page=page;void sync(page);return}if(!submitted.value)return;generation++;submitted.value={...submitted.value,page};void load()}
function tick(){if(!props.events){void load();return}countdown.value=nextRefresh?Math.max(0,Math.ceil((nextRefresh-Date.now())/1000)):0;if(nextRefresh&&Date.now()>=nextRefresh){nextRefresh=0;if(autoRefresh.value&&!changed.value&&!document.hidden&&!busy)void load()}}
function changeTab(value:string){tab.value=value;filter.status='';filter.source='';filter.recipient='';detail.value=undefined;void sync()}
async function inspect(row:Record<string,unknown>){const current=generation;try{const value=isNotifications.value?await api<Record<string,unknown>>(`/api/notifications/${row.id}?channel=${channel.value}`):row;if(current===generation)detail.value=value}catch(e){if(current===generation)error.value=errorMessage(e)}}
function time(row:Record<string,unknown>){return Number(row.time||row.since||0)}
function text(row:Record<string,unknown>){const event=row.event as Record<string,unknown>|undefined;return String(row.message||event?.path||event?.reason||row.kind||'')}
function kind(row:Record<string,unknown>){const event=row.event as Record<string,unknown>|undefined;const raw=String(row.kind||event?.operation||row.source||'');const labels:Record<string,string>={website:'网站',health:'监控链路',legacy:'历史通知',test:'测试',host_watchdog:'中心看门狗',outage:'网站访问',certificate:'证书有效期',slow:'响应缓慢',create:'新增文件',modify:'修改文件',delete:'删除文件',move:'移动文件',scan:'安全扫描',probe:'链路探针',cpu:'CPU',memory:'内存',unreachable:'采集失联',node_unreachable:'采集失联',disk:'磁盘空间',inode:'inode 使用率',clock:'时钟同步',agent:'文件监控心跳',local_probe:'本地监控测试',central_probe:'中心接收链路',event_query:'事件入库查询',scanner:'安全扫描心跳',coverage:'监控目录覆盖',vector:'事件传输',agent_metric_missing:'Agent 指标缺失',inotify_overflow:'文件监听溢出',dropped:'事件丢弃',backlog:'事件积压'};return labels[raw]||labels[raw.split(':')[0]!]||raw||'通知'}
function eventData(row:Record<string,unknown>){return (row.event||row.metadata||{}) as Record<string,unknown>}
function scanLabel(value:unknown){return ({pending:'等待扫描',matched:'发现可疑特征',no_match:'未发现可疑特征',error:'扫描失败',skipped:'已跳过'} as Record<string,string>)[String(value)]||'尚未记录'}
function riskLabel(value:unknown){return ({high:'高风险',critical:'严重风险',medium:'中风险',low:'低风险',unclassified:'待核查'} as Record<string,string>)[String(value)]||'尚未分类'}
function reasonLabel(value:unknown){const labels:Record<string,string>={event_delivery_rejected:'事件被中心拒绝，记录已保留；请检查投递失败原因',scanner_exit:'扫描超时或执行失败',scanner_failed:'扫描程序无法启动',content_changed_before_scan:'扫描前文件再次变化',scan_size_changed:'扫描期间文件大小发生变化',scan_symlink_path:'文件路径为符号链接',scanner_unavailable:'扫描服务不可用'};return labels[String(value)]||String(value||'—')}
function eventTime(row:Record<string,unknown>){const tm=Date.parse(String(eventData(row).time||''));return Number.isFinite(tm)?tm/1000:0}
function state(row:Record<string,unknown>){if(props.events){const event=eventData(row),scan=event.scan as Record<string,unknown>|undefined;return event.operation==='scan'?scanLabel(scan?.status):event.risk?riskLabel(event.risk):'已记录'};if(tab.value==='email')return ({delivered:'已提交邮件服务器',partial:'部分成功',paused:'已暂停',pending:'待发送',retrying:'重试中'} as Record<string,string>)[String(row.status)]||'待发送';if(row.source==='website'&&row.phase==='resolved')return '已结束';return row.phase==='reminder'?'持续提醒':statusLabel(String(row.status||row.phase||''))}
function recipients(row:Record<string,unknown>){return ((row.recipients||[]) as {recipient:string}[]).map(v=>v.recipient).join('、')}
function visibility(){documentHidden.value=document.hidden;if(document.hidden){nextRefresh=0;countdown.value=0}else if(!props.events || autoRefresh.value&&submitted.value&&!changed.value)void load()}
watch(()=>route.fullPath,()=>{parseRoute();detail.value=undefined;if(props.events){nextRefresh=0;countdown.value=0}else{generation++;void load()}})
onMounted(async()=>{parseRoute();try{nodes.value=(await servers()).items}catch{}if(disposed)return;if(props.events){try{const saved=Number(localStorage.getItem(preferenceKey()));if(refreshIntervals.includes(saved))intervalSeconds.value=saved}catch{}}else await load();if(disposed)return;timer=setInterval(tick,props.events?1000:30000);document.addEventListener('visibilitychange',visibility)})
onUnmounted(()=>{disposed=true;generation++;clearInterval(timer);clearTimeout(inputTimer);document.removeEventListener('visibilitychange',visibility)})
</script>
<template>
<el-alert v-if="error" :title="error" type="error" :closable="false" />
<el-card shadow="never"><div class="card-heading"><span></span><router-link :to="{path:'/settings',query:{group:'历史与备份',storage:'1',node:filter.node,category:events?'events':tab==='history'?(filter.source==='website'?'website':filter.source==='health'?'server':'all'):'notifications'}}">存储与清理 →</router-link></div><div v-if="!events" class="filters"><el-button v-for="[value,label] in [['current','当前异常'],['history','告警历史'],['notifications','飞书通知'],['email','邮箱通知']]" :key="value" :type="tab===value?'primary':''" @click="changeTab(value!)">{{label}}</el-button></div>
<div class="filters">
<el-select v-model="filter.node" clearable :value-on-clear="''" placeholder="全部服务器" @change="sync()"><el-option v-for="n in nodes" :key="n.id" :label="n.name" :value="n.id" /></el-select>
<el-select v-if="!events&&!isNotifications" v-model="filter.source" clearable :value-on-clear="''" placeholder="全部分类" @change="sync()"><el-option value="website" label="网站"/><el-option value="health" label="服务器"/></el-select>
<el-input v-model="filter.q" clearable placeholder="搜索原因、文件或消息" @input="search" @keyup.enter="submit()" @clear="sync()" />
<el-select v-model="filter.hours" @change="sync()"><el-option v-for="[hours,label] in [[24,'最近 24 小时'],[168,'最近 7 天'],[720,'最近 30 天']]" :key="hours" :value="hours" :label="String(label)" /></el-select>
<el-select v-if="isNotifications" v-model="filter.status" clearable :value-on-clear="''" placeholder="全部投递状态" @change="sync()"><el-option v-for="s in tab==='email'?['delivered','partial','pending','retrying','paused']:['delivered','pending','retrying']" :key="s" :value="s" :label="state({status:s})" /></el-select>
<el-input v-if="tab==='email'" v-model="filter.recipient" clearable placeholder="搜索收件邮箱" @input="search" @keyup.enter="submit()" @clear="sync()"/>
<el-select v-if="events" v-model="filter.operation" clearable :value-on-clear="''" placeholder="全部事件类型" @change="sync()"><el-option v-for="[value,label] in [['create','新增'],['modify','修改'],['delete','删除'],['move','移动'],['scan','安全扫描'],['health','监控异常'],['test','测试'],['probe','链路探针']]" :key="value" :value="value" :label="label" /></el-select>
<el-switch v-if="events" v-model="filter.include_probes" aria-label="包含链路探针" active-text="包含链路探针" @change="sync()" /><el-button data-testid="event-query" type="primary" @click="submit()">查询</el-button></div>
<div v-if="events" class="event-refresh"><el-switch data-testid="auto-refresh" aria-label="自动刷新" v-model="autoRefresh" :disabled="!queried" active-text="自动刷新" @change="schedule" /><el-select data-testid="refresh-interval" aria-label="自动刷新间隔" v-model="intervalSeconds" placeholder="刷新间隔（秒）" @change="intervalSeconds=Number(intervalSeconds);configureRefresh()"><el-option v-for="n in refreshIntervals" :key="n" :value="n" :label="`${n} 秒`" /></el-select><span v-if="!queried">请先查询，再开启自动刷新</span><span v-else-if="changed">已暂停，等待提交筛选</span><span v-else-if="autoRefresh">{{documentHidden?'后台标签已暂停':loading?'正在刷新':`下次刷新：${countdown} 秒`}}</span><span v-if="lastUpdated">最近更新：{{beijingTime(lastUpdated)}}</span></div>
<el-alert v-if="changed" title="筛选条件已修改，点击查询更新；下方仍为上一次查询结果。" type="info" :closable="false"/>
<RecordDelete v-if="events&&queried||!events&&tab!=='current'" ref="deletion" :records="checked" :label="events?'文件与安全历史':isNotifications?'通知历史':'告警历史'" history @done="load"/><el-empty v-if="events&&!queried&&!loading&&!error" description="请选择筛选条件，点击查询查看记录" />
<el-table v-else v-loading="loading" :data="items" @selection-change="checked=$event" :empty-text="error?'查询失败，请重试':'当前筛选条件下暂无记录'"><el-table-column v-if="events&&queried||!events&&tab!=='current'" type="selection" :selectable="(row:Record<string,unknown>)=>!!row.can_delete" width="48"/><el-table-column label="时间（北京时间）" min-width="190"><template #default="{row}">{{beijingTime(time(row))}}</template></el-table-column><el-table-column label="服务器 / 网站" min-width="150"><template #default="{row}">{{row.name||nodes.find(n=>n.id===row.node)?.name||row.node||'监控中心'}}</template></el-table-column><el-table-column label="类型" min-width="120"><template #default="{row}">{{kind(row)}}</template></el-table-column><el-table-column :label="tab==='email'?'主题':'问题 / 内容'" min-width="280"><template #default="{row}"><el-button link type="primary" class="wrap" @click="inspect(row)">{{row.subject||text(row)}}</el-button></template></el-table-column><el-table-column v-if="tab==='email'" label="收件人" min-width="220"><template #default="{row}">{{recipients(row)}}</template></el-table-column><el-table-column label="状态" min-width="140"><template #default="{row}">{{state(row)}}</template></el-table-column><el-table-column v-if="tab==='history'" label="结束时间 / 持续时长" min-width="220"><template #default="{row}">{{row.ended?beijingTime(Number(row.ended)):row.source==='website'?'仍在持续':'—'}}<small style="display:block">{{durationText(row.duration_seconds)}}{{row.source==='health'&&row.phase!=='resolved'&&row.duration_seconds!=null?'（截至本条事件）':''}}</small></template></el-table-column><el-table-column v-if="events&&queried||!events&&tab!=='current'" label="删除保护" min-width="210"><template #default="{row}"><el-button link type="danger" :disabled="!row.can_delete" @click="deletion?.open([row])">删除</el-button><small class="muted">{{row.delete_reason}}</small></template></el-table-column>
</el-table>
<el-pagination :current-page="events?Number(submitted?.page||1):filter.page" :total="total" :page-size="20" layout="total, prev, pager, next" @update:current-page="paginate"/>
<p class="muted">{{events?'文件变化及安全扫描属于历史事件，链路探针默认隐藏。':tab==='email'?'已提交邮件服务器不代表进入收件箱或已读。关闭邮件通知时未完成任务暂停，重新开启后继续发送。':'飞书已送达表示接口确认成功，不代表已读。文件变化属于事件，测试消息不计入异常。'}}</p></el-card>
<MetricChart v-if="isNotifications" :title="tab==='email'?'最近 7 天邮箱通知结果':'最近 7 天飞书通知结果'" :option="chart"/>
<el-dialog :model-value="!!detail" title="记录详情" width="min(850px,96vw)" @update:model-value="detail=undefined"><template v-if="detail"><p>服务器 / 网站：{{detail.name||nodes.find(n=>n.id===detail?.node)?.name||detail.node||'监控中心'}}</p><p>类型：{{kind(detail)}} · 状态：{{state(detail)}}</p><p>发生时间：{{beijingTime(events?eventTime(detail):Number(detail.started||detail.time||0))}}</p><p v-if="!isNotifications">结束时间：{{detail.ended?beijingTime(Number(detail.ended)):'—'}} · 持续时长：{{durationText(detail.duration_seconds)}}</p><template v-if="events"><p>记录入库：{{beijingTime(Number(detail.time||0))}}</p><p>文件路径：{{eventData(detail).path || '—'}}</p><p v-if="eventData(detail).old_path">原文件路径：{{eventData(detail).old_path}}</p><p>风险分类：{{riskLabel(eventData(detail).risk)}}</p><template v-if="eventData(detail).scan"><p>扫描结果：{{scanLabel((eventData(detail).scan as Record<string,unknown>).status)}}</p><p>扫描原因：{{reasonLabel((eventData(detail).scan as Record<string,unknown>).reason)}}</p></template><p v-if="eventData(detail).reason">运行原因：{{reasonLabel(eventData(detail).reason)}}</p></template><pre v-else class="detail-text">{{text(detail)}}</pre><router-link v-if="detail.site" :to="`/websites/${detail.site}`" @click="detail=undefined">查看网站详情 →</router-link><el-table v-if="detail.recipients" :data="detail.recipients"><el-table-column prop="recipient" label="收件人"/><el-table-column prop="attempts" label="尝试次数"/><el-table-column prop="result" label="最近结果"/><el-table-column label="下次重试"><template #default="{row}">{{row.done?'已完成':beijingTime(row.next_try)}}</template></el-table-column></el-table><el-table v-if="detail.records" :data="detail.records"><el-table-column prop="recipient" label="收件人"/><el-table-column label="尝试时间"><template #default="{row}">{{beijingTime(row.time)}}</template></el-table-column><el-table-column prop="result" label="结果"/></el-table></template></el-dialog>
</template>
<style scoped>.detail-text{white-space:pre-wrap;overflow-wrap:anywhere;max-height:50vh;overflow:auto;line-height:1.6}</style>